<template><div class="scr-global-status" role="status" aria-live="polite" :class="{ 'is-error': result && !result.success }"><strong>{{ core.busy ? core.progress?.label : (result?.message || t('app.ready')) }}</strong><span v-if="!core.busy && core.seed">{{ core.seed }}</span><button v-if="core.busy || result" type="button" @click="$emit('details')">{{ t('common.details') }}</button></div></template>
<script setup>import { computed } from "vue"; import { useStores } from "../../stores/index.js"; defineEmits(["details"]); const stores = useStores(); const core = stores.core.state; const result = computed(() => core.lastResult); const { t } = stores.i18n</script>
